      "quote": "Evaluating the effectiveness of substance use disorder treatment centers: a systematic review of international standards and outcomes",
      "reason": "The title explicitly includes the phrase \"a systematic review\"."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Evaluating the effectiveness of substance use disorder treatment centers: a systematic review of international standards and outcomes",
      "reason": "The title identifies the population (\"substance use disorder treatment centers\") and the objective/outcome (\"evaluating the effectiveness\" and \"international standards and outcomes\")."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
