{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Despite extensive international research evaluating SUD treatment center effectiveness, previous studies suffer from several knowledge gaps that necessitate this systematic review. Firstly, a lack of consensus on standardized international indicators for measuring treatment success has hindered comparisons across studies (9, 10). Many studies focus on limited criteria, such as short-term abstinence rates, while improvements in quality of life, reintegration into society, and psychosocial functioning, as critical dimensions of treatment success, have received less attention. Secondly, the diversity of treatment approaches and variability in study design (for example, short follow-up periods, small sample sizes, and heterogeneous measurement tools) has prevented existing findings from providing a coherent framework for policymaking or clinical improvement(9, 11, 12). Thirdly, a deficiency of robust evidence on the long-term impact of interventions, particularly in non-physiological domains such as family cohesion or employment, is among the research gaps(13, 14).",
      "reason": "The text explicitly describes the current state of knowledge (extensive research exists) and identifies specific uncertainties and gaps (lack of consensus on indicators, limited criteria, variability in study design, and lack of long-term evidence)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Understanding the outcomes of SUD treatment centers is essential for optimizing clinical practices, informing policy decisions, and improving patient care. ... Consequently, there is a need to identify clear, internationally recognized indicators of treatment success to standardize evaluations and facilitate comparisons across different settings.",
      "reason": "The text explains the importance of the review by linking it to the need for optimizing clinical practices, informing policy, and standardizing evaluations to facilitate comparisons."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not mention the existence of previous similar systematic reviews that would necessitate an update or replication; therefore, this conditional requirement does not apply."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Treatment centers offer a variety of interventions, including pharmacotherapy, behavioral therapies, and multidisciplinary approaches combining medical, psychological, and social interventions.",
      "reason": "The review covers interventions for SUD, and the text briefly describes the mechanisms/types of interventions (pharmacotherapy, behavioral therapies, multidisciplinary approaches) being evaluated."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not present a formal logic model, and while it discusses complex interventions, the requirement to consider a logic model is conditional and not explicitly required if not used by the authors."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "This study aims to address the following research questions: First, what are the key international indicators and standards for measuring the success of addiction treatment? Second, which treatment modalities used in SUD treatment centers are most effective in improving abstinence rates, preventing relapse, enhancing quality of life (QoL), and facilitating social reintegration among patients?",
      "reason": "The review explicitly states its research questions and objectives in the introduction section."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "The PICO framework-Population, Intervention, Comparison, Outcome ، was utilized to structure the research question and guide the review process(20). This framework helps in analyzing the impact of interventions on treatment outcomes and facilitates the development of effective therapeutic strategies. Table 1 presents the PICO components for this review.",
      "reason": "The review evaluates intervention effects (SUD treatment centers) and explicitly states the use of the PICO framework to structure the research question and guide the review process, referencing a table of PICO components."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "Inclusion criteria comprised studies examining treatment outcomes in SUD treatment centers; studies exploring management innovations in health crises within SUD treatment centers; peer-reviewed articles published in reputable scientific journals; articles written in English; studies providing empirical data or conducting analytical reviews; and articles published between January 2000 and December 2024. Exclusion criteria comprised studies focusing on healthcare systems outside the SUD context; articles reviewing healthcare innovations in crises unrelated to SUD; literary reviews lacking systematic analysis or empirical evidence; studies published in languages other than English; articles published before 2000; and editorials, commentaries, and opinion pieces without original data.",
      "reason": "The manuscript explicitly lists inclusion and exclusion criteria, covering study types, settings, and empirical nature."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "Inclusion criteria comprised ... peer-reviewed articles published in reputable scientific journals; articles written in English; ... and articles published between January 2000 and December 2024. Exclusion criteria comprised ... studies published in languages other than English; articles published before 2000; and editorials, commentaries, and opinion pieces without original data.",
      "reason": "The manuscript specifies report characteristics including language, publication date range, and publication status (peer-reviewed vs. editorials/commentaries)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript lists 'irrelevant outcomes' as an exclusion reason but does not distinguish between studies excluded because outcomes were not measured versus those excluded because results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "While the manuscript mentions that studies were included in a 'qualitative synthesis,' it does not specify how studies were grouped for these syntheses (e.g., by intervention type, population, or outcome)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "The date restriction to 2000 was chosen because it marks the widespread adoption of buprenorphine and the shift toward evidence-based pharmacological treatment in SUD care(21). Studies before this date largely reflect outdated treatment paradigms that are not generalizable to current practice.",
      "reason": "The manuscript provides a clear rationale for the notable restriction on the publication date."
    }
  ],
  "confidence": 100
}

